/**
 * GENERATED FILE PRODUCER — writes lib/geometry/__fixtures__/phase17-channel-litres-pin.json: the litres of the 49
 * channelled boards (`phase17ChannelBoards`, lib/geometry/__fixtures__/phase17-channel-boards.ts) exactly as the app
 * reads them today, BEFORE the finished rail's rule for channels changes (Phase 17, plan 17-19, gap G-17-6; D-20's
 * pin-first habit). The output is generated and must never be hand-edited.
 *
 *   npx --no-install tsx --tsconfig ./tsconfig.json scripts/extract-phase17-channel-litres-pin.ts
 *
 * run from the repository root. It is a record of the code as it stood, so it REFUSES to run once
 * `lib/geometry/volume.ts` names `sectionsOffAt` (17-20's new seam input): from then on the figures it would write
 * are the new code's own, and the pin would prove nothing. It ran exactly once, before the channel rule changed.
 * (Nothing in package.json — `--no-install` means npx can only run the tsx already in node_modules. No database.)
 *
 * Each figure is `summarizeDesign(fields).volumeLitres.toPrecision(17)`, a string, so the test compares every digit a
 * double holds.
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { phase17ChannelBoards } from "@/lib/geometry/__fixtures__/phase17-channel-boards";
import { summarizeDesign } from "@/lib/geometry/design";

const VOLUME = path.resolve(process.cwd(), "lib/geometry/volume.ts");
const OUTPUT = path.resolve(process.cwd(), "lib/geometry/__fixtures__/phase17-channel-litres-pin.json");

function main() {
  if (!existsSync(VOLUME)) {
    throw new Error("Run this from the repository root (lib/geometry/volume.ts not found here).");
  }
  if (readFileSync(VOLUME, "utf8").includes("sectionsOffAt")) {
    throw new Error("the pin records the litres from before the channel rule changed — it is never re-run");
  }
  const litres: Record<string, string> = {};
  for (const board of phase17ChannelBoards()) {
    litres[board.label] = summarizeDesign(board.fields).volumeLitres.toPrecision(17);
  }
  const provenance =
    "GENERATED by scripts/extract-phase17-channel-litres-pin.ts from the app as it stood before the finished rail's " +
    "rule for channels changed (Phase 17, plan 17-19, G-17-6; phase17ChannelBoards, summarizeDesign, toPrecision(17); " +
    "base commit 8d6b3164, 2026-11-10) — never hand-edit, never re-run";
  writeFileSync(OUTPUT, `${JSON.stringify({ provenance, litres }, null, 2)}\n`);
  for (const [label, value] of Object.entries(litres)) console.log(`${label}: ${Number(value).toFixed(4)} L`);
  console.log(`wrote ${path.relative(process.cwd(), OUTPUT)} (${Object.keys(litres).length} boards)`);
}

try {
  main();
} catch (error: unknown) {
  console.error(error instanceof Error ? error.message : error);
  process.exitCode = 1;
}
